@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--bg:#080b14;--panel:#101521;--panel2:#141b29;--line:rgba(164,184,218,.12);--text:#eef3fc;--muted:#758198;--gold:#e8bc73;--cyan:#73d8dc;--violet:#a88af2;--red:#e77b83;--font:'Manrope',sans-serif}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--font);font-size:13px}body{overflow-x:hidden;background:radial-gradient(ellipse at 56% 48%,#151b2a 0,#0b0f19 54%,#080b14 100%)}button{font:inherit;color:inherit;border:0;cursor:pointer}#app{min-height:100vh;max-width:1920px;margin:auto;position:relative;overflow:hidden}.topbar{height:66px;display:flex;align-items:center;padding:0 31px;border-bottom:1px solid rgba(165,183,212,.1);background:rgba(8,11,20,.75);position:relative;z-index:3}.brand{display:flex;align-items:center;gap:11px;color:#f3f5fb;text-decoration:none;font-size:13px;font-weight:800;letter-spacing:1.55px}.brand-mark{font-size:23px;color:var(--gold);text-shadow:0 0 18px #e8bc7375}.brand-muted{color:#8f9ab0;margin-left:4px;font-weight:600}.season{margin-left:60px;color:#9faabd;font:10px 'DM Mono',monospace;letter-spacing:1.25px}.season-divider{color:#4b5465;margin:0 7px}.live-dot,.ping-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#71d8be;box-shadow:0 0 9px #71d8be;margin-right:8px}.top-actions{margin-left:auto;display:flex;align-items:center;gap:12px}.icon-btn{width:31px;height:31px;border:1px solid var(--line);border-radius:8px;background:#111725;color:#abb7ca;font-weight:700}.icon-btn:hover{color:white;border-color:#67748c}.profile{display:flex;align-items:center;gap:9px;margin-left:12px;padding-left:17px;border-left:1px solid var(--line);font-size:11px}.profile-avatar{width:29px;height:29px;display:grid;place-items:center;border-radius:9px;background:linear-gradient(145deg,#39415f,#1d2434);color:#eac67e;font-size:17px}.profile-name{font-weight:700}.profile-level{font:9px 'DM Mono',monospace;color:#e4bd7b;background:#28241e;padding:5px 7px;border-radius:4px}.game-layout{display:grid;grid-template-columns:220px minmax(500px,1fr) 302px;gap:19px;padding:20px 27px 24px;min-height:calc(100vh - 66px)}.left-rail,.right-rail{display:flex;flex-direction:column;gap:13px;min-width:0}.panel{background:linear-gradient(145deg,rgba(18,24,37,.96),rgba(14,19,30,.97));border:1px solid var(--line);border-radius:10px;box-shadow:0 7px 26px #0000001c}.match-panel{padding:18px 17px 16px;position:relative;overflow:hidden}.match-panel:after{content:'✦';position:absolute;right:-5px;top:-21px;color:#e8bc730c;font-size:110px}.panel-kicker,.arena-eyebrow{font:9px 'DM Mono',monospace;color:#8794aa;letter-spacing:1.5px}.match-title{font-size:23px;line-height:1.11;letter-spacing:-.7px;font-weight:800;margin:10px 0 17px}.round-line{display:flex;align-items:center;gap:7px;font:10px 'DM Mono',monospace;color:#8591a5}.round-line strong{font-size:17px;color:#f3f4f8}.round-slash{color:#444d5d}.phase-pill{display:inline-flex;align-items:center;gap:7px;background:#252218;color:#e5c181;font:9px 'DM Mono',monospace;padding:7px 9px;border-radius:4px;margin-top:12px;letter-spacing:.7px}.phase-dot{width:5px;height:5px;border-radius:50%;background:#e8bc73;box-shadow:0 0 8px #e8bc73}.phase-pill.battle{background:#29191d;color:#f08d91}.phase-pill.battle .phase-dot{background:#ef7e83;box-shadow:0 0 8px #ef7e83}.timer-wrap{margin-top:15px}.timer-label{display:flex;align-items:center;justify-content:space-between;font:9px 'DM Mono',monospace;color:#79849a}.timer-label strong{font-size:14px;color:#f0f3f9}.timer-track{height:3px;background:#242a38;border-radius:4px;margin-top:8px;overflow:hidden}.timer-track div{height:100%;width:100%;background:linear-gradient(90deg,#d9ac68,#f1d29a);transition:width .3s}.section-heading{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;letter-spacing:1.1px;color:#aab5c8}.tiny-muted{color:#657187;font-size:8px;letter-spacing:.7px}.standings-panel{padding:15px 15px 11px}.standings-panel .section-heading{margin-bottom:13px}.standing{height:34px;display:flex;align-items:center;gap:8px;border-top:1px solid #ffffff08;font-size:10px}.standing:first-child{border-top:0}.standing-rank{font:9px 'DM Mono',monospace;color:#77839a;width:12px}.standing-avatar{width:21px;height:21px;border-radius:7px;display:grid;place-items:center;background:#20283a;color:#c6a9f6;font-size:12px}.standing-name{flex:1;color:#c3cada;font-weight:600}.standing-hp{font:9px 'DM Mono',monospace;color:#8aa393}.standing.you .standing-name{color:#f0ca85}.standing.you .standing-avatar{background:#383022;color:#e9bf73}.traits-panel{padding:15px;flex:1;min-height:128px}.traits-panel .section-heading{margin-bottom:12px}.traits-list{display:flex;flex-direction:column;gap:7px}.empty-traits{font-size:10px;line-height:1.7;color:#69758a;padding:3px 0}.trait-row{display:flex;align-items:center;gap:8px;padding:7px 8px;background:#ffffff04;border:1px solid #ffffff08;border-radius:6px}.trait-icon{width:25px;height:25px;border-radius:6px;display:grid;place-items:center;font-size:14px;background:#25263c;color:#bda2f2}.trait-info{flex:1;min-width:0}.trait-name{font-size:10px;font-weight:700;color:#d9deea}.trait-progress{font:8px 'DM Mono',monospace;color:#77849b;margin-top:2px}.trait-bonus{font:8px 'DM Mono',monospace;color:#8dd3c4}.trait-row.active{border-color:#a88af233;background:#a88af20a}.left-footer{font:8px 'DM Mono',monospace;color:#687489;padding:2px 3px;letter-spacing:.4px}.left-footer span:last-child{margin-left:5px}.arena-column{min-width:0;display:flex;flex-direction:column}.arena-head{height:67px;display:flex;justify-content:space-between;align-items:flex-start}.arena-eyebrow{font-size:8px;color:#8390a6;letter-spacing:1.7px}.arena-head h1{font-size:21px;letter-spacing:-.7px;margin:5px 0 0;font-weight:700}.arena-head h1 span{color:#77839a;font-weight:500}.arena-stats{display:flex;gap:22px;padding-top:10px}.arena-stats>div{display:grid;grid-template-columns:auto auto;align-items:center;column-gap:5px}.arena-stats>div span:nth-child(2){font:16px 'DM Mono',monospace;color:#f2d094}.arena-stats small{grid-column:2;font:8px 'DM Mono',monospace;color:#738097;letter-spacing:.6px}.stat-icon{grid-row:span 2;font-size:14px}.stat-icon.cyan{color:#76d8d1}.arena-frame{height:min(55vh,520px);min-height:365px;position:relative;overflow:hidden;border:1px solid rgba(160,181,212,.19);border-radius:10px;background:#0d1421;box-shadow:0 15px 55px #0007,inset 0 0 70px #080b14aa}#three-root{position:absolute;inset:0}#three-root canvas{width:100%;height:100%;display:block;touch-action:none}.arena-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0b101d9c 0%,transparent 24%,transparent 73%,#090d18b3 100%),radial-gradient(ellipse at 50% 49%,transparent 50%,#080b1466 100%)}.arena-overlay-top,.arena-overlay-bottom{position:absolute;left:18px;right:18px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.arena-overlay-top{top:15px}.enemy-label{display:flex;align-items:center;gap:9px}.enemy-emblem{display:grid;place-items:center;width:34px;height:34px;border:1px solid #d7807540;border-radius:9px;background:#2b1d23;color:#df8b80;font-size:19px}.enemy-label b,.enemy-label small{display:block}.enemy-label b{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#e6d9d3}.enemy-label small{font:8px 'DM Mono',monospace;letter-spacing:.8px;color:#bd7777;margin-top:4px}.wave-badge{display:flex;align-items:center;gap:8px;padding:6px 9px;background:#101522c9;border:1px solid #ffffff13;border-radius:5px}.wave-badge span{font:8px 'DM Mono',monospace;color:#8995a8}.wave-badge b{font:13px 'DM Mono',monospace;color:#edc681}.arena-overlay-bottom{bottom:13px}.battle-message{background:#101622d9;border:1px solid #ffffff14;border-radius:5px;padding:8px 11px;color:#b4bfd0;font-size:10px;display:flex;gap:8px;align-items:center;max-width:70%}.message-icon{color:#e6c27c}.arena-controls{font:7px 'DM Mono',monospace;color:#738096;letter-spacing:.6px}.arena-controls i{font-style:normal;color:#ac8ce9;margin:0 7px}.arena-corner{position:absolute;width:14px;height:14px;border-color:#bca16b;opacity:.7;pointer-events:none}.corner-tl{left:5px;top:5px;border-left:1px solid;border-top:1px solid}.corner-tr{right:5px;top:5px;border-right:1px solid;border-top:1px solid}.corner-bl{left:5px;bottom:5px;border-left:1px solid;border-bottom:1px solid}.corner-br{right:5px;bottom:5px;border-right:1px solid;border-bottom:1px solid}.board-caption{height:30px;display:flex;align-items:center;gap:18px;font:8px 'DM Mono',monospace;color:#7e899d;letter-spacing:.5px}.board-caption i{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:5px}.legend-player{background:#83dad2;box-shadow:0 0 7px #83dad2}.legend-enemy{background:#ed7d83;box-shadow:0 0 7px #ed7d83}.caption-right{margin-left:auto;color:#67748a}.caption-right b{color:#ac8de3;margin:0 5px}.bench-section{margin-top:auto}.bench-head{display:flex;align-items:center;justify-content:space-between;margin:9px 0 9px}.small-link{background:none;color:#858fa2;font:8px 'DM Mono',monospace;letter-spacing:.5px}.small-link span{color:var(--gold);margin-left:5px}.bench-grid{display:grid;grid-template-columns:repeat(7,minmax(55px,1fr));gap:8px}.bench-slot{height:81px;border:1px dashed #626f8538;border-radius:7px;background:#11172571;display:flex;align-items:center;justify-content:center;position:relative;transition:.18s;cursor:pointer}.bench-slot:hover,.bench-slot.drag-over{border-color:#d8b97988;background:#d8b9790d}.bench-slot .empty-plus{font-size:16px;color:#3d485c}.unit-card{border:1px solid #ffffff18;background:linear-gradient(145deg,#20283a,#111724);border-radius:7px;position:relative;overflow:hidden;cursor:grab;transition:transform .15s,border .15s;user-select:none}.unit-card:hover{transform:translateY(-2px);border-color:#c4a36a88}.unit-card:active{cursor:grabbing}.bench-slot .unit-card{width:100%;height:100%;padding:7px}.card-art{height:32px;display:grid;place-items:center;font-size:24px;text-shadow:0 0 14px currentColor;position:relative}.card-art:after{content:'';position:absolute;bottom:-4px;left:15%;right:15%;height:1px;background:currentColor;opacity:.55;box-shadow:0 0 9px currentColor}.card-name{font-size:9px;font-weight:800;margin-top:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-class{font:7px 'DM Mono',monospace;color:#8f9bb0;margin-top:3px;white-space:nowrap}.card-price{position:absolute;right:6px;top:5px;font:8px 'DM Mono',monospace;color:#f0c77d}.unit-card.dragging{opacity:.35}.sell-mode .bench-slot{border-color:#e77b8370}.right-rail{gap:12px}.shop-panel{padding:15px}.shop-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px}.shop-heading h2{margin:4px 0 0;font-size:17px;letter-spacing:-.4px}.refresh-cost{font:10px 'DM Mono',monospace;color:#e9c47e;background:#28251f;border:1px solid #574730;padding:5px 7px;border-radius:5px}.refresh-cost span{font-size:14px;vertical-align:-1px;margin-right:3px}.shop-cards{display:flex;flex-direction:column;gap:6px}.shop-unit{height:59px;display:flex;align-items:center;padding:6px 8px;gap:9px;background:linear-gradient(90deg,#1b2232,#151b28);border:1px solid #ffffff0d;border-radius:6px;cursor:pointer;transition:.16s;position:relative;overflow:hidden}.shop-unit:hover{border-color:#d8b97970;transform:translateX(-2px)}.shop-unit:before{content:'';position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--unit-color)}.shop-art{font-size:25px;width:33px;text-align:center;color:var(--unit-color);filter:drop-shadow(0 0 8px currentColor)}.shop-info{flex:1;min-width:0}.shop-name{font-size:10px;font-weight:800}.shop-meta{font:8px 'DM Mono',monospace;color:#8793a7;margin-top:4px}.shop-price{font:9px 'DM Mono',monospace;color:#eac47f}.refresh-btn{width:100%;height:31px;margin-top:9px;border-radius:5px;background:#26221c;color:#e6c181;font:9px 'DM Mono',monospace;letter-spacing:.6px;border:1px solid #403828}.refresh-btn:hover{background:#332b20}.refresh-btn span{font-size:13px;vertical-align:-1px;margin-right:5px}.refresh-btn small{margin-left:8px;color:#a28b62}.shop-foot{display:flex;justify-content:space-between;align-items:center;margin-top:9px;font:7px 'DM Mono',monospace;color:#68758a;letter-spacing:.2px}.shop-foot b{color:#9ba6b7;font-weight:500}.shop-foot i{font-style:normal;color:#475164;margin:0 3px}.army-panel{padding:13px 15px;min-height:95px}.army-panel .section-heading{margin-bottom:10px}.army-list{display:flex;gap:6px;flex-wrap:wrap}.army-chip{display:flex;align-items:center;gap:5px;border:1px solid #ffffff0f;border-radius:5px;padding:5px 6px;background:#ffffff05;color:#c7cfdd;font-size:8px}.army-chip span:first-child{font-size:13px}.army-empty{font-size:9px;color:#69758a}.fusion-panel{padding:13px 14px 11px}.fusion-panel .section-heading{margin-bottom:10px}.codex-glyph{font-size:15px;color:#d8bc82}.fusion-feature{display:flex;align-items:center;gap:8px;padding:7px 0;border-top:1px solid #ffffff0a}.fusion-icon{width:27px;height:27px;display:grid;place-items:center;border-radius:7px;background:#28281f;color:#e5c276;font-size:17px}.fusion-violet{background:#25203a;color:#b59af5}.fusion-feature div:nth-child(2){flex:1}.fusion-feature b{font-size:9px}.fusion-feature p{font-size:8px;color:#7e899d;margin:3px 0 0}.fusion-lock{font:7px 'DM Mono',monospace;color:#727d90;border:1px solid #343b4b;padding:3px 4px;border-radius:3px}.fusion-lock.unlocked{color:#7ed1ba;border-color:#45836d66;background:#1a302b}.fusion-note{font-size:8px;line-height:1.5;color:#738096;margin-top:5px}.right-actions{display:grid;grid-template-columns:1fr 1.35fr;gap:8px;margin-top:auto}.secondary-btn,.battle-btn{height:45px;border-radius:6px;display:flex;align-items:center;justify-content:center}.secondary-btn{background:#202635;border:1px solid #ffffff11;gap:7px;color:#cbd4e3}.secondary-btn>span:first-child{color:#e8c278;font-size:15px}.secondary-btn>span:nth-child(2){font-size:9px;font-weight:800;letter-spacing:.4px}.secondary-btn small{display:block;font:7px 'DM Mono',monospace;color:#a98c5d;margin-top:3px}.secondary-btn b{font:8px 'DM Mono',monospace;color:#8490a2}.secondary-btn i{font-style:normal;color:#e8c278}.battle-btn{position:relative;background:linear-gradient(105deg,#d9b36f,#c68e53);color:#181610;font-size:9px;font-weight:800;letter-spacing:.75px;gap:8px;box-shadow:0 4px 18px #c79b5430;transition:.15s}.battle-btn:hover{filter:brightness(1.13);transform:translateY(-1px)}.battle-glyph{font-size:15px}.btn-arrow{position:absolute;right:10px;font-size:15px}.toast{position:fixed;z-index:9;left:50%;bottom:28px;transform:translate(-50%,20px);padding:10px 16px;border:1px solid #d8b97950;border-radius:6px;background:#171c28;color:#f0d195;font-size:11px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 8px 30px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#05070dcc;display:grid;place-items:center;padding:20px;opacity:0;pointer-events:none;transition:opacity .2s;backdrop-filter:blur(8px)}.modal-backdrop.open{opacity:1;pointer-events:auto}.modal-card{width:min(430px,100%);background:linear-gradient(145deg,#171e2d,#101521);border:1px solid #b7a16d44;border-radius:12px;padding:28px;position:relative;box-shadow:0 20px 90px #000b}.modal-close{position:absolute;right:13px;top:10px;background:none;color:#8793a7;font-size:22px}.modal-spark{font-size:28px;color:#e9c47e;margin-bottom:12px}.modal-card h2{font-size:23px;margin:6px 0}.modal-card>p{color:#94a0b3;font-size:11px;line-height:1.6}.guide-row{display:flex;gap:12px;padding:11px 0;border-top:1px solid #ffffff0c;font-size:10px;color:#9ba7ba;line-height:1.5}.guide-row>b{font:10px 'DM Mono',monospace;color:#dfbd7d}.guide-row strong{color:#e6eaf1}.modal-play{width:100%;margin-top:12px}.modal-play .btn-arrow{position:static;margin-left:auto;margin-right:10px}
@media(min-width:1500px){.game-layout{grid-template-columns:245px minmax(600px,1fr) 330px;gap:24px;padding:24px 40px}.arena-frame{height:min(59vh,600px)}.bench-slot{height:92px}.shop-unit{height:64px}.match-panel{padding:20px}}
