 const bodyGeo=u.side==='enemy'?new THREE.SphereGeometry(.34,16,12):new THREE.CapsuleGeometry(.25,.46,5,9);const body=mesh(bodyGeo,armor,group);body.position.y=.77;body.scale.set(u.side==='enemy'?1.2:1,.9,u.side==='enemy'?1.12:1);
