function syncCharacters(){for(const u of state.units){if(u.alive&&!u.group)createCharacter(u);if(!u.alive&&u.group)removeCharacter(u);}}

function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function alivePlayers(){return state.units.filter(u=>u.side==='player'&&u.alive)}
function placedCount(){return alivePlayers().filter(u=>u.row>=3).length;}
function updateHUD(){
 $('#goldCount').textContent=state.gold;$('#unitCount').textContent=`${placedCount()} / ${state.level}`;$('#armyTotal').textContent=`${alivePlayers().length} UNITS`;
 $('#levelText').textContent=state.level;$('#roundLabel').textContent=String(state.round).padStart(2,'0');$('#waveNumber').textContent=String(state.round).padStart(2,'0');
 const pill=$('#phasePill');pill.classList.toggle('battle',state.phase==='battle');pill.innerHTML=`<span class="phase-dot"></span> ${state.phase==='battle'?'IN BATTLE':'PREPARATION'}`;
 $('#timerCaption').textContent=state.phase==='battle'?'COMBAT':'PREP PHASE';$('#timerText').textContent=state.phase==='battle'?Math.max(0,Math.ceil(25-state.combatElapsed)):Math.ceil(state.prepTime);
 $('#timerBar').style.width=`${Math.max(0,(state.phase==='battle'?25-state.combatElapsed:state.prepTime)/30*100)}%`;
 $('#battleBtnText').textContent=state.phase==='battle'?'BATTLE IN PROGRESS':'BEGIN BATTLE';$('#battleBtn').disabled=state.phase==='battle';$('#battleBtn').style.opacity=state.phase==='battle'?'.62':'1';
 $('#weatherName').textContent=['AURORA VEIL','STARFALL DRIFT','EMBER TIDE','MOONGLASS FOG'][(state.round-1)%4];
 const bench=$('#bench');bench.innerHTML='';const reserves=state.units.filter(u=>u.side==='player'&&u.alive&&u.row<0);
 for(let i=0;i<7;i++){const slot=document.createElement('div');slot.className='bench-slot';slot.dataset.slot=String(i);if(reserves[i])slot.append(makeCard(reserves[i]));else slot.innerHTML='<span class="empty-plus">+</span>';slot.addEventListener('click',()=>{if(reserves[i]){if(state.sellMode)sellUnit(reserves[i]);else{state.selected=reserves[i];showToast(`${reserves[i].name} selected — choose a tile on your half.`);}}});slot.addEventListener('dragover',e=>{e.preventDefault();slot.classList.add('drag-over')});slot.addEventListener('dragleave',()=>slot.classList.remove('drag-over'));slot.addEventListener('drop',e=>{e.preventDefault();slot.classList.remove('drag-over');const id=Number(e.dataTransfer.getData('unit'));const u=state.units.find(x=>x.id===id);if(u&&u.row>=3&&state.phase==='prep')moveToBench(u);});bench.append(slot);}
 renderShop();renderArmy();renderTraits();renderStandings();syncCharacters();
}
function makeCard(u){const d=CLASS_DATA[u.type],card=document.createElement('div');card.className='unit-card';card.draggable=state.phase==='prep';card.dataset.id=u.id;card.innerHTML=`<div class="card-price">${'★'.repeat(u.star)}</div><div class="card-art" style="color:${d.color}">${d.icon}</div><div class="card-name">${u.name}</div><div class="card-class">${d.role}</div>`;card.title=`${u.name} · ${d.role} · ${d.skill}`;card.addEventListener('dragstart',e=>{draggingUnit=u;card.classList.add('dragging');e.dataTransfer.setData('unit',String(u.id));});card.addEventListener('dragend',()=>{draggingUnit=null;card.classList.remove('dragging')});card.addEventListener('click',e=>{e.stopPropagation();if(state.sellMode)sellUnit(u);else if(u.row<0){state.selected=u;showToast(`${u.name} selected — choose a tile on your half.`)}});return card;}
function renderShop(){const holder=$('#shopCards');holder.innerHTML='';state.shop.forEach((type,index)=>{const d=CLASS_DATA[type],cost=unitCost(type);const card=document.createElement('div');card.className='shop-unit';card.style.setProperty('--unit-color',d.color);card.innerHTML=`<div class="shop-art">${d.icon}</div><div class="shop-info"><div class="shop-name">${d.name}</div><div class="shop-meta">${d.role.toUpperCase()} · ${d.skill}</div></div><div class="shop-price">◈ ${cost}</div>`;card.title=`${d.name} — ${d.desc}`;card.addEventListener('click',()=>buyUnit(index));holder.append(card);});}
function renderArmy(){const list=$('#armyList');list.innerHTML='';const units=alivePlayers();if(!units.length){list.innerHTML='<span class="army-empty">No champions recruited yet.</span>';return;}units.slice(0,10).forEach(u=>{const d=CLASS_DATA[u.type],chip=document.createElement('div');chip.className='army-chip';chip.title=`${u.name}: ${d.skill} — ${d.desc}`;chip.innerHTML=`<span style="color:${d.color}">${d.icon}</span><span>${u.name}${u.star>1?' ★'+u.star:''}</span>`;list.append(chip);});}
function renderTraits(){const holder=$('#traitsList');holder.innerHTML='';const counts={};for(const u of alivePlayers())counts[CLASS_DATA[u.type].trait]=(counts[CLASS_DATA[u.type].trait]||0)+1;const active=Object.entries(counts).filter(([t,n])=>n>=2);$('#traitCount').textContent=`${active.length}/8`;if(!active.length){holder.innerHTML='<div class="empty-traits">Deploy units to awaken<br>their ancient bonds.</div>';}else active.forEach(([trait,count])=>{const row=document.createElement('div');row.className='trait-row active';row.innerHTML=`<div class="trait-icon">${TRAIT_ICONS[trait]||'✦'}</div><div class="trait-info"><div class="trait-name">${trait}</div><div class="trait-progress">${count} / 2 · ${traitBonus(trait)}</div></div><div class="trait-bonus">ACTIVE</div>`;holder.append(row);});
 for(const fusion of FUSIONS){const unlocked=(counts[fusion.a]||0)>0&&(counts[fusion.b]||0)>0;const el=$(`#${fusion.id}`);if(el){el.textContent=unlocked?'AWAKENED':'LOCKED';el.classList.toggle('unlocked',unlocked);}}
}
function traitBonus(trait){return ({Vanguard:'+25% armor',Arcanist:'+20% spell power',Ranger:'+1 range',Beast:'+12% lifesteal',Stormcaller:'chain lightning',Duelist:'+20% attack speed',Celestial:'+10% healing',Void:'+15% spell vamp',Frostborn:'slow on hit',Tinker:'random boosts',Dragonkin:'+20% skill damage',Guardian:'+15% max health',Wraith:'+10% damage',Wayfinder:'+1 starting mana'})[trait]||'team resonance';}
function renderStandings(){const names=['MossKnight','VelvetHex','YOU','LittleComet','IronWisp','Moonfox','AshenVale','OrbitKid'];const list=$('#standings');list.innerHTML='';names.forEach((name,i)=>{const you=name==='YOU';const row=document.createElement('div');row.className=`standing${you?' you':''}`;const hp=you?state.hp:Math.max(12,100-Math.max(0,state.round-i-2)*8);row.innerHTML=`<span class="standing-rank">${i+1}</span><span class="standing-avatar">${['♞','☽','✧','☼','⬟','❄','ϟ','◉'][i]}</span><span class="standing-name">${name}</span><span class="standing-hp">${hp}♥</span>`;list.append(row);});}
function unitCost(type){return ['dragon','oracle','wraith'].includes(type)?4:['storm','duelist','guardian','voidling','frost'].includes(type)?3:2;}
function rollShop(){const weights=SHOP_POOL.map(t=>t);state.shop=Array.from({length:4},()=>weights[Math.floor(Math.random()*weights.length)]);renderShop();}
function buyUnit(index){if(state.phase!=='prep')return showToast('Wait until preparation to recruit.');const type=state.shop[index];if(!type)return;const cost=unitCost(type);if(state.gold<cost)return showToast('Not enough gold.');if(state.units.filter(u=>u.side==='player'&&u.alive&&u.row<0).length>=7)return showToast('Your reserve bench is full.');state.gold-=cost;const u=makeUnit(type,'player',0,-1);u.hp=u.maxHp;state.units.push(u);state.shop.splice(index,1);mergeTriples();updateHUD();showToast(`${u.name} joined your reserve bench.`);}
function refreshShop(){if(state.gold<2)return showToast('You need 2 gold to refresh.');if(state.phase!=='prep')return showToast('The market is closed during battle.');state.gold-=2;rollShop();updateHUD();}
function mergeTriples(){let changed=true;while(changed){changed=false;const players=state.units.filter(u=>u.side==='player'&&u.alive);for(const type of SHOP_POOL){const copies=players.filter(u=>u.type===type);if(copies.length>=3){const star=Math.min(3,copies[0].star+1);if(star===copies[0].star)continue;const chosen=copies.slice(0,3);chosen[0].star=star;chosen[0].maxHp=Math.round(chosen[0].maxHp*1.65);chosen[0].hp=chosen[0].maxHp;chosen[0].attack=Math.round(chosen[0].attack*1.5);chosen.slice(1).forEach(u=>{u.alive=false;});showToast(`FUSION! ${chosen[0].name} reached ★${star}.`);changed=true;break;}}}}
function moveToBench(u){if(state.phase!=='prep')return;u.row=-1;u.col=0;u.x=0;u.z=0;state.selected=null;updateHUD();}
function sellUnit(u){if(state.phase!=='prep')return showToast('You can only sell during preparation.');u.alive=false;state.gold+=Math.max(1,unitCost(u.type)-u.star+1);state.sellMode=false;$('#sellMode').classList.remove('active');updateHUD();showToast(`${u.name} sold for gold.`);}
function placeSelected(col,row){if(state.phase!=='prep')return;const u=state.selected||draggingUnit;if(!u)return;if(row<3)return showToast('Deploy on the three rows closest to you.');if(placedCount()>=state.level&&u.row<0)return showToast('Army limit reached — buy XP to raise your level.');const occupying=alivePlayers().find(x=>x!==u&&x.row===row&&x.col===col);if(occupying){if(u.row<0)return showToast('That tile is occupied.');const c=u.col,r=u.row;occupying.col=c;occupying.row=r;occupying.x=c-3.5;occupying.z=r-2.5;if(occupying.group){occupying.group.position.set(occupying.x,0,occupying.z);}}u.col=col;u.row=row;u.x=col-3.5;u.z=row-2.5;if(u.group)u.group.position.set(u.x,0,u.z);state.selected=null;mergeTriples();updateHUD();}
function buyXP(){if(state.gold<4)return showToast('Not enough gold for experience.');if(state.level>=8)return showToast('You have reached the maximum level.');state.gold-=4;state.xp+=4;if(state.xp>=4){state.level++;state.xp-=4;showToast(`Level up! Your army limit is now ${state.level}.`);}updateHUD();}

