function buyXP(){if(state.gold<4)return showToast('Not enough gold for experience.');if(state.level>=8)return showToast('You have reached the maximum level.');state.gold-=4;state.xp+=4;if(state.xp>=4){state.level++;state.xp-=4;showToast(`Level up! Your army limit is now ${state.level}.`);}updateHUD();}

function spawnWave(){state.units=state.units.filter(u=>u.side==='player'&&u.alive);const types=state.round<3?['monster','imp','golem']:['monster','wyrm','golem','imp'];const count=Math.min(5,Math.min(2+Math.floor(state.round/2),types.length));for(let i=0;i<count;i++){const type=types[(i+state.round-1)%types.length],col=1+Math.floor(i*6/Math.max(1,count-1));const u=makeUnit(type,'enemy',col,1+(i%2));u.name=CLASS_DATA[type].name;u.maxHp=85+state.round*14+(type==='golem'?35:0);u.hp=u.maxHp;u.attack=10+state.round*1.6+(type==='golem'?4:0);u.range=['imp','wyrm'].includes(type)?3:1.55;u.rate=1.55;state.units.push(u);}}
function beginBattle(){if(state.phase!=='prep')return;state.selected=null;state.sellMode=false;$('#sellMode').classList.remove('active');state.phase='battle';state.combatElapsed=0;state.prepTime=30;state.units.filter(u=>u.side==='player'&&u.alive).forEach(u=>{u.hp=u.maxHp;u.attackClock=.4+Math.random()*.5;u.mana=15;});state.units.filter(u=>u.side==='enemy'&&u.alive).forEach(u=>{u.hp=u.maxHp;});$('#battleMessage').innerHTML='<span class="message-icon">⚔</span> <span>Your champions have entered the fray!</span>';updateHUD();}
function finishRound(won){if(state.phase!=='battle')return;state.phase='prep';state.combatElapsed=0;if(won){state.roundWins++;state.gold+=5+Math.floor(state.round/3);$('#battleMessage').innerHTML='<span class="message-icon">✦</span> <span>Victory! The Wilds yielded gold and a moment to regroup.</span>';showToast(`Wave ${state.round} defeated · +${5+Math.floor(state.round/3)} gold`);}else{state.hp=Math.max(0,state.hp-12);$('#battleMessage').innerHTML='<span class="message-icon">✦</span> <span>Your formation was broken. Regroup and try again.</span>';showToast('Defeat · your tactician lost 12 health.');}
 if(state.hp<=0){state.hp=100;state.gold=Math.max(8,state.gold);state.round=1;state.roundWins=0;showToast('A new convergence begins. Your tactician was revived.');}
 state.round=state.round>=12?1:state.round+1;state.prepTime=30;spawnWave();state.units.filter(u=>u.side==='player'&&u.alive).forEach(u=>{u.hp=u.maxHp;u.row=u.row<0?-1:u.row;});updateHUD();}
function distance(a,b){return Math.hypot(a.x-b.x,a.z-b.z);}
function targetFor(u){const foes=state.units.filter(v=>v.alive&&v.side!==u.side);if(!foes.length)return null;return foes.reduce((best,v)=>distance(u,v)<distance(u,best)?v:best,foes[0]);}
function applyDamage(target,amount,source,kind='normal'){if(!target.alive)return;let dmg=Math.max(1,Math.round(amount));if(target.ward>0){const blocked=Math.min(target.ward,dmg);target.ward-=blocked;dmg-=blocked;}target.hp-=dmg;target.hitFlash=.18;refreshHealth(target);spawnBeam(source,target,kind==='skill'?0xeac677:(source.side==='enemy'?0xf07882:0x77decc),kind==='skill');if(target.hp<=0){target.hp=0;target.alive=false;target.group?.scale.setScalar(.85);if(source.side==='player'&&source.type==='wraith')source.attack+=2;}}
function triggerSkill(u,target){const trait=CLASS_DATA[u.type].trait;u.mana=0;const opponents=state.units.filter(v=>v.alive&&v.side!==u.side),allies=state.units.filter(v=>v.alive&&v.side===u.side);switch(u.type){
 case 'beast':{u.hp=Math.min(u.maxHp,u.hp+22);allies.filter(v=>distance(v,u)<3.2).forEach(v=>{v.attack+=2;});spawnRing(u,0xe4a56e);break;}
 case 'storm':{applyDamage(target,u.attack*1.55,u,'skill');const chain=opponents.filter(v=>v!==target&&distance(v,target)<3.3).slice(0,2);chain.forEach(v=>applyDamage(v,u.attack*.8,u,'skill'));break;}
 case 'arcanist':case 'dragon':case 'imp':{const nearby=opponents.filter(v=>distance(v,target)<2.4);nearby.forEach(v=>applyDamage(v,u.attack*1.65,u,'skill'));break;}
 case 'oracle':{const wounded=allies.slice().sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(wounded){wounded.hp=Math.min(wounded.maxHp,wounded.hp+36);refreshHealth(wounded);spawnRing(wounded,0xe8c879);}break;}
 case 'voidling':case 'wraith':{const dmg=u.attack*1.7;applyDamage(target,dmg,u,'skill');u.hp=Math.min(u.maxHp,u.hp+dmg*.55);break;}
 case 'frost':{opponents.filter(v=>distance(v,u)<3.5).forEach(v=>{applyDamage(v,u.attack*1.1,u,'skill');v.slow=1.5;});spawnRing(u,0x93d8fa);break;}
 case 'guardian':case 'golem':{opponents.filter(v=>distance(v,u)<2.2).forEach(v=>{applyDamage(v,u.attack*1.3,u,'skill');v.stun=.65;});spawnRing(u,0xaab5c4);break;}
 case 'sentinel':{u.ward+=36;spawnRing(u,0x91c8d6);break;}
 case 'duelist':{applyDamage(target,u.attack*1.6,u,'skill');u.attackClock-=.45;break;}
 case 'ranger':case 'wyrm':{applyDamage(target,u.attack*2.15,u,'skill');break;}
 case 'alchemist':{const ally=allies[Math.floor(Math.random()*allies.length)];if(ally){ally.attack+=4;ally.hp=Math.min(ally.maxHp,ally.hp+15);spawnRing(ally,0xd2ce78);}break;}
 default:applyDamage(target,u.attack*1.5,u,'skill');
 }u.skillReady=true;setTimeout(()=>{u.skillReady=false;},400);}
function spawnBeam(a,b,color,bright=false){if(!a.group||!b.group)return;const start=new THREE.Vector3(a.x,.9,a.z),end=new THREE.Vector3(b.x,.86,b.z);const geometry=new THREE.BufferGeometry().setFromPoints([start,end]);const material=new THREE.LineBasicMaterial({color,transparent:true,opacity:bright?.95:.65});const line=new THREE.Line(geometry,material);fxGroup.add(line);line.userData.life=bright?.25:.14;}
function spawnRing(u,color){if(!u.group)return;const ring=new THREE.Mesh(new THREE.TorusGeometry(.35,.035,6,24),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.set(u.x,.17,u.z);ring.userData={life:.5,ring:true};fxGroup.add(ring);}
function updateCombat(dt){if(state.phase!=='battle')return;state.combatElapsed+=dt;for(const u of state.units){if(!u.alive||u.side==='player'&&u.row<0)continue;u.stun=Math.max(0,(u.stun||0)-dt);u.slow=Math.max(0,(u.slow||0)-dt);if(u.stun>0)continue;const target=targetFor(u);if(!target)continue;const dx=target.x-u.x,dz=target.z-u.z,dist=Math.hypot(dx,dz)||.001;const reach=u.range+(target.type==='golem'?.2:0);if(dist>reach-.12){const speed=(u.slow>0?.55:1)*(u.type==='duelist'?2.2:1.5);u.x+=dx/dist*speed*dt;u.z+=dz/dist*speed*dt;u.group?.position.set(u.x,0,u.z);}else{u.attackClock-=dt;if(u.attackClock<=0){u.attackClock=u.rate*(u.type==='duelist'?.82:1);const bonus=1+(u.star-1)*.7+(CLASS_DATA[u.type].trait==='Vanguard'?.1:0);const damage=u.attack*bonus*(u.side==='enemy'?1:1);applyDamage(target,damage,u);u.mana=Math.min(100,u.mana+38);if(u.mana>=100)triggerSkill(u,target);}}
 }
 const foes=state.units.filter(u=>u.alive&&u.side==='enemy');if(!foes.length){finishRound(true);return;}if(state.combatElapsed>28){finishRound(alivePlayers().length>0);return;}if(!alivePlayers().length){finishRound(false);return;}}
function pickBoardCell(event){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((event.clientX-rect.left)/rect.width)*2-1;pointer.y=-((event.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const plane=new THREE.Plane(new THREE.Vector3(0,1,0),0);const point=new THREE.Vector3();if(!raycaster.ray.intersectPlane(plane,point))return;const col=Math.round(point.x+3.5),row=Math.round(point.z+2.5);if(col>=0&&col<8&&row>=0&&row<6)placeSelected(col,row);}
renderer.domElement.addEventListener('pointerdown',e=>{cameraDrag={x:e.clientX,y:e.clientY,angle:camAngle,moved:false};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!cameraDrag)return;const dx=e.clientX-cameraDrag.x,dy=e.clientY-cameraDrag.y;if(Math.abs(dx)+Math.abs(dy)>4)cameraDrag.moved=true;if(cameraDrag.moved&&!state.selected){camAngle=cameraDrag.angle-dx*.006;cameraUpdate();}});renderer.domElement.addEventListener('pointerup',e=>{if(cameraDrag&&!cameraDrag.moved){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((e.clientX-rect.left)/rect.width)*2-1;pointer.y=-((e.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(entityGroup.children,true);let picked=null;for(const hit of hits){let obj=hit.object;while(obj&&obj!==entityGroup){if(obj.userData.unit){picked=obj.userData.unit;break;}obj=obj.parent;}if(picked)break;}if(picked&&picked.side==='player'&&state.phase==='prep'){state.selected=picked;showToast(`${picked.name} selected — choose a tile to reposition.`);}else if(state.selected)pickBoardCell(e);}cameraDrag=null;});renderer.domElement.addEventListener('wheel',e=>{camRadius=THREE.MathUtils.clamp(camRadius+e.deltaY*.012,15,30);cameraUpdate();},{passive:true});
// Add unit metadata at group root so character meshes can be picked.
function attachUnitMetadata(){for(const u of state.units)if(u.group)u.group.userData.unit=u;}

